<?php require_once 'config.php';$id=(int)($_GET['id']??0);$s=db()->prepare("SELECT c.*,u.name trainer_name FROM courses c LEFT JOIN users u ON c.trainer_id=u.id WHERE c.id=? AND (c.status='published' OR c.trainer_id=?)");$s->execute([$id,logged_in()?current_user()['id']:0]);$course=$s->fetch();if(!$course){http_response_code(404);$pageTitle='Course not found';require 'includes/header.php';echo '<section class="empty-state"><h2>Course not found</h2><a href="courses.php">Back to courses</a></section>';require 'includes/footer.php';exit;}$pageTitle=$course['title'];$isEnrolled=false;$materials=[];$assessments=[];if(logged_in()){$s=db()->prepare('SELECT id FROM enrollments WHERE user_id=? AND course_id=?');$s->execute([current_user()['id'],$id]);$isEnrolled=(bool)$s->fetch();}$s=db()->prepare('SELECT * FROM resources WHERE course_id=? ORDER BY created_at DESC');$s->execute([$id]);$materials=$s->fetchAll();$s=db()->prepare('SELECT * FROM assessments WHERE course_id=? ORDER BY created_at DESC');$s->execute([$id]);$assessments=$s->fetchAll();require 'includes/header.php'; ?>
<section class="detail-hero"><a class="back-link" href="courses.php">← All courses</a><span class="eyebrow"><?= e($course['category']?:'LEARNING PATH') ?></span><h1><?= e($course['title']) ?></h1><p><?= e($course['description']) ?></p><div class="detail-byline">Created by <b><?= e($course['trainer_name']??'Capacity Connect') ?></b></div><?php if(logged_in()&&current_user()['role']==='trainee'&&!$isEnrolled): ?><form method="post" action="enroll.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="course_id" value="<?= $id ?>"><button class="btn btn-light">Enroll in this course →</button></form><?php elseif($isEnrolled): ?><span class="status-pill">✓ You're enrolled</span><?php elseif(!logged_in()): ?><a class="btn btn-light" href="login.php">Log in to enroll →</a><?php endif; ?></section><section class="detail-layout"><div class="detail-main"><span class="eyebrow">COURSE OVERVIEW</span><h2>What you'll learn</h2><p class="detail-description"><?= nl2br(e($course['description'])) ?></p><h2>Learning resources</h2><?php if($materials): ?><div class="resource-list"><?php foreach($materials as $r): ?><div class="resource-item"><span class="resource-icon">↗</span><div><b><?= e($r['title']) ?></b><small><?= e($r['resource_type']) ?><?= $r['url']?' · External resource':'' ?></small></div><?php if($r['url']): ?><a href="<?= e($r['url']) ?>" target="_blank" rel="noopener">Open ↗</a><?php elseif($r['file_path']): ?><a href="<?= e($r['file_path']) ?>" target="_blank" rel="noopener">View ↗</a><?php endif; ?></div><?php endforeach; ?></div><?php else: ?><p class="muted">No learning resources have been added yet.</p><?php endif; ?><h2>Assessments</h2><?php if($assessments): ?><div class="resource-list"><?php foreach($assessments as $a): ?><div class="resource-item"><span class="resource-icon">✓</span><div><b><?= e($a['title']) ?></b><small><?= (int)$a['total_marks'] ?> marks · <?= (int)$a['question_count'] ?> questions</small></div><?php if($isEnrolled): ?><a href="assessment.php?id=<?= (int)$a['id'] ?>">Start →</a><?php else: ?><span class="muted">Enroll first</span><?php endif; ?></div><?php endforeach; ?></div><?php else: ?><p class="muted">No assessments available yet.</p><?php endif; ?></div><aside class="detail-side"><div class="side-card"><span class="eyebrow">COURSE DETAILS</span><div class="side-detail"><span>Category</span><b><?= e($course['category']?:'General') ?></b></div><div class="side-detail"><span>Trainer</span><b><?= e($course['trainer_name']??'Not assigned') ?></b></div><div class="side-detail"><span>Format</span><b>Self-paced</b></div><div class="side-detail"><span>Access</span><b>Online resources</b></div></div></aside></section><?php require 'includes/footer.php'; ?>
